import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"پہلے مشاہدہ پھر محدود مداخلت کے رہنما اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/83-先观测后有限干涉准则.md","filePath":"ur/83-先观测后有限干涉准则.md"}'),d={name:"ur/83-先观测后有限干涉准则.md"};function h(l,t,i,u,n,q){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="پہلے-مشاہدہ-پھر-محدود-مداخلت-کے-رہنما-اصول" tabindex="-1">پہلے مشاہدہ پھر محدود مداخلت کے رہنما اصول <a class="header-anchor" href="#پہلے-مشاہدہ-پھر-محدود-مداخلت-کے-رہنما-اصول" aria-label="Permalink to &quot;پہلے مشاہدہ پھر محدود مداخلت کے رہنما اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>83</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>پہلے مشاہدہ، محدود مداخلت، مشاہدہ پروٹوکول، مداخلت کی حد، وجوہات کی تشخیص</td></tr></tbody></table><h2 id="_1-رہنما-اصول-کا-بنیادی-فلسفہ" tabindex="-1">1. رہنما اصول کا بنیادی فلسفہ <a class="header-anchor" href="#_1-رہنما-اصول-کا-بنیادی-فلسفہ" aria-label="Permalink to &quot;1. رہنما اصول کا بنیادی فلسفہ&quot;">​</a></h2><p>&quot;پہلے مشاہدہ پھر محدود مداخلت&quot; ہینگ یوان ژو کے وقت کے پیچھے ہٹنے اور بین السطح آثار قدیمہ کے آپریشن کا بنیادی رہنما اصول ہے، اس کا بنیادی فلسفہ سولہ حروف میں خلاصہ کیا جا سکتا ہے: &quot;دیکھو لیکن چھو نہ، ناپو لیکن پریشان نہ کرو، جانچو پھر کام کرو، کام کرو لیکن حد میں۔&quot; اس رہنما اصول کا قیام کائنات کے وجوہاتی قوانین کے لیے گہری تعظیم پر مبنی ہے — ماضی یا دوسری سطح پر کوئی بھی براہ راست مداخلت غیر متوقع وجوہاتی سلسلہ واکنش کا باعث بن سکتی ہے، اور کافی پیشگی مشاہدہ خطرے کو کم سے کم کرنے کا واحد قابل اعتماد ذریعہ ہے۔</p><p>رہنما اصول کی فلسفیانہ بنیاد &quot;علمی عاجزی&quot; کا اصول ہے۔ ہینگ یوان ژو تسلیم کرتا ہے کہ یہاں تک کہ سطح کے سب سے بلند طاقتور شخص بھی کسی وقت کے نوڈ یا کسی سطح کی تہذیب کے تمام وجوہاتی تعلقات کو مکمل طور پر حاصل نہیں کر سکتا۔ لہذا، کسی بھی مداخلت کے اقدام سے پہلے، سب سے زیادہ محتاط رویے کے ساتھ مکمل مشاہدہ کرنا ضروری ہے، ہدف چیز کی وجوہاتی ساخت اور ارتقاء کے رجحان کو زیادہ سے زیادہ مکمل طور پر سمجھنا۔ صرف مشاہدے کے ڈیٹا کافی، خطرے کی تشخیص واضح ہونے کی شرط پر، محدود مداخلت کی اجازت دی جاتی ہے۔</p><p>&quot;پہلے مشاہدہ پھر محدود مداخلت&quot; دو آزادانہ مراحل نہیں ہیں، بلکہ ایک نامیاتی آپریشن بند چکر ہے: مشاہدہ مداخلت کے لیے بنیاد فراہم کرتا ہے، اور مداخلت کے نتائج نئے مشاہدے کے ڈیٹا کے طور پر دوبارہ ردعمل دیتے ہیں، دونوں چکراتی طور پر آگے بڑھتے ہیں۔ یہ بند چکر اس بات کو یقینی بناتا ہے کہ ہر مداخلت تازہ ترین، سب سے مکمل علم کی بنیاد پر قائم ہو۔</p><h2 id="_2-مشاہدے-کے-مرحلے-کے-آپریشن-اصول" tabindex="-1">2. مشاہدے کے مرحلے کے آپریشن اصول <a class="header-anchor" href="#_2-مشاہدے-کے-مرحلے-کے-آپریشن-اصول" aria-label="Permalink to &quot;2. مشاہدے کے مرحلے کے آپریشن اصول&quot;">​</a></h2><p>مشاہدہ کا مرحلہ پورے آپریشن کے عمل کی بنیاد ہے، اس کا معیار براہ راست بعد کی مداخلت کی حفاظت اور تاثیر کا تعین کرتا ہے۔ مشاہدے کے مرحلے میں درج ذیل آپریشن اصولوں پر عمل کرنا ضروری ہے:</p><h3 id="_2-1-مشاہدے-کی-مدت-کا-تقاضا" tabindex="-1">2.1 مشاہدے کی مدت کا تقاضا <a class="header-anchor" href="#_2-1-مشاہدے-کی-مدت-کا-تقاضا" aria-label="Permalink to &quot;2.1 مشاہدے کی مدت کا تقاضا&quot;">​</a></h3><p>مشاہدے کی مدت ہدف مدت کی کل لمبائی کے 1% سے کم نہیں ہونی چاہیے، اور مطلق مدت اپنی سطح کے معیاری وقت کے 72 گھنٹے سے کم نہیں ہونی چاہیے۔ مثال کے طور پر، 100 سال کی مدت والے تاریخی مدت پر پیچھے ہٹنے کا مشاہدہ کرنے کے لیے، خالص مشاہدے کا مرحلہ 1 سال سے کم نہیں ہونا چاہیے؛ 10 سال کی مدت والے مدت پر مشاہدہ کرنے کے لیے، خالص مشاہدے کا مرحلہ 72 گھنٹے سے کم نہیں ہونا چاہیے۔ اس کم از کم مدت کے تقاضے سے یہ یقینی بنتا ہے کہ مشاہدہ کار ہدف مدت کے اندر متواتر تبدیلیوں اور طویل مدتی رجحانات کو پکڑ سکے، مشاہدے کی ونڈو بہت چھوٹی ہونے کی وجہ سے یک طرفہ فیصلے سے بچا جا سکے۔</p><h3 id="_2-2-مشاہدے-کے-جہتوں-کا-تقاضا" tabindex="-1">2.2 مشاہدے کے جہتوں کا تقاضا <a class="header-anchor" href="#_2-2-مشاہدے-کے-جہتوں-کا-تقاضا" aria-label="Permalink to &quot;2.2 مشاہدے کے جہتوں کا تقاضا&quot;">​</a></h3><p>مشاہدہ میں درج ذیل پانچ جہتیں شامل ہونی چاہئیں، ایک بھی نہیں ہونی چاہیے:</p><table tabindex="0"><thead><tr><th>مشاہدے کی جہت</th><th>مخصوص مواد</th><th>مشاہدے کا طریقہ</th></tr></thead><tbody><tr><td>مادہ کی جہت</td><td>جغرافیائی ماحول، ماحولیاتی نظام، بنیادی ڈھانچہ، مادی وسائل کی تقسیم</td><td>جگہ اسکیننگ، مادہ تجزیہ</td></tr><tr><td>توانائی کی جہت</td><td>توانائی کی کثافت کی تقسیم، قانون کے پیرامیٹر، توانائی کے بہاؤ کا نمونہ</td><td>توانائی سپیکٹرم تجزیہ، قانون کی کھوج</td></tr><tr><td>زندگی کی جہت</td><td>پرجاتیوں کی تقسیم، آبادی کی تعداد، صحت کی حالت، ارتقاء کی سطح</td><td>زندگی کی علامات اسکیننگ، جین کا نمونہ</td></tr><tr><td>شعور کی جہت</td><td>تہذیب کی شکل، سماجی ڈھانچہ، فکری تصورات، اجتماعی شعور کا رجحان</td><td>شعور ڈومین غیر فعال سننا، ثقافتی تجزیہ</td></tr><tr><td>وجوہات کی جہت</td><td>کلیدی وجوہاتی زنجیریں، تاریخی نوڈز، ارتقاء کے رجحانات، ممکنہ خطرات</td><td>وجوہاتی زنجیر ٹریکنگ، رجحان کا اندازہ</td></tr></tbody></table><h3 id="_2-3-مشاہدے-کی-غیر-جانبداری-کا-تقاضا" tabindex="-1">2.3 مشاہدے کی غیر جانبداری کا تقاضا <a class="header-anchor" href="#_2-3-مشاہدے-کی-غیر-جانبداری-کا-تقاضا" aria-label="Permalink to &quot;2.3 مشاہدے کی غیر جانبداری کا تقاضا&quot;">​</a></h3><p>مشاہدے کے مرحلے میں سختی سے غیر جانبداری برقرار رکھنی چاہیے، مشاہدہ کار کسی بھی طرح سے مشاہدے کی چیز کو متاثر نہیں کر سکتا۔ مخصوص ممنوع اعمال میں شامل ہیں: مشاہدے کی چیز کے ساتھ کسی بھی طرح کے رابطے، مشاہدے کے علاقے میں کوئی مادہ یا توانائی کا نشان چھوڑنا، مشاہدے کی چیز کے رویے کی رہنمائی یا اشارہ کرنا، اور شعور ڈومین میں کوئی قابل احساس خواہش کے اتار چڑھاؤ کو چھوڑنا۔</p><p>مشاہدے کے مرحلے میں مشاہدہ کار کے وجود کی حالت &quot;خالص غیر فعال ادراک&quot; ہونی چاہیے، یعنی صرف معلومات وصول کرنا بغیر کوئی معلومات جاری کیے۔ اینکر اینکرنگ ڈیوائس مشاہدہ کار کے لیے ایک &quot;مشاہدہ پردہ میدان&quot; پیدا کرے گا، اس بات کو یقینی بنائے گا کہ مشاہدہ کار کے وجود کو مشاہدے کی چیز محسوس نہیں کر سکے، ساتھ ہی مشاہدہ کار کو غیر ارادی طور پر مداخلت کرنے والے سگنل جاری کرنے سے روکے گا۔</p><h2 id="_3-محدود-مداخلت-کی-تعریف-اور-حد" tabindex="-1">3. محدود مداخلت کی تعریف اور حد <a class="header-anchor" href="#_3-محدود-مداخلت-کی-تعریف-اور-حد" aria-label="Permalink to &quot;3. محدود مداخلت کی تعریف اور حد&quot;">​</a></h2><p>مشاہدے کا مرحلہ مکمل ہونے کے بعد، آپریشن ٹیم کو &quot;مشاہدہ رپورٹ اور مداخلت کی عملداری کی تشخیص&quot; جمع کروانا ہوگا، وقت قانون کمیٹی یا سطح انتظامیہ بیورو کی منظوری کے بعد ہی، محدود مداخلت کے مرحلے میں داخل کیا جا سکتا ہے۔ &quot;محدود مداخلت&quot; میں &quot;محدود&quot; درج ذیل تین سطحوں پر ظاہر ہوتا ہے:</p><h3 id="_3-1-محدود-دائرہ-کار" tabindex="-1">3.1 محدود دائرہ کار <a class="header-anchor" href="#_3-1-محدود-دائرہ-کار" aria-label="Permalink to &quot;3.1 محدود دائرہ کار&quot;">​</a></h3><p>مداخلت کا عمل منظوری دستاویز میں مقررہ &quot;مداخلت کی اجازت والے علاقے&quot; میں سختی سے محدود ہونا چاہیے، یہ علاقہ عام طور پر مشاہدے کے علاقے کے کل رقبے کے 1% سے زیادہ نہیں ہوتا۔ اجازت والے علاقے سے باہر کوئی بھی مداخلت کا عمل خلاف ورزی والے آپریشن کے طور پر شمار ہوگا، آپریٹر قانونی ذمہ داری اٹھائے گا۔</p><h3 id="_3-2-محدود-ڈگری" tabindex="-1">3.2 محدود ڈگری <a class="header-anchor" href="#_3-2-محدود-ڈگری" aria-label="Permalink to &quot;3.2 محدود ڈگری&quot;">​</a></h3><p>مداخلت کی توانائی کی پیداوار اور معلومات کے انجیکشن کی مقدار &quot;مداخلت کی حد&quot; سے زیادہ نہیں ہونی چاہیے۔ مداخلت کی حد ہدف چیز کی وجوہاتی حساسیت کے مطابق متحرک طور پر طے کی جاتی ہے، حساب کا فارمولا یہ ہے: مداخلت کی حد = ہدف علاقے کی کل توانائی × وجوہاتی حساسیت کا گتانک × 0.0001۔ جہاں وجوہاتی حساسیت کا گتانک کی قدر کی حد 0.1 سے 10 ہے، تہذیب کی ڈگری جتنی زیادہ، تاریخی نوڈ جتنا اہم، گتانک اتنا بڑا۔ اس کا مطلب ہے کہ اہم تاریخی نوڈز پر مداخلت کی حد انتہائی کم ہے، تقریباً کسی بھی حقیقی توانائی کے انجیکشن کی اجازت نہیں ہے۔</p><h3 id="_3-3-محدود-وقت" tabindex="-1">3.3 محدود وقت <a class="header-anchor" href="#_3-3-محدود-وقت" aria-label="Permalink to &quot;3.3 محدود وقت&quot;">​</a></h3><p>مداخلت کے عمل کی جاری مدت مشاہدے کے مرحلے کی کل مدت کے 10% سے زیادہ نہیں ہونی چاہیے، اور مطلق مدت اپنی سطح کے معیاری وقت کے 24 گھنٹے سے زیادہ نہیں ہونی چاہیے۔ مداخلت ختم ہونے کے بعد، آپریٹر کو فوری طور پر ہدف مدت یا ہدف سطح سے انخلاء کرنا چاہیے، رہنا نہیں چاہیے۔</p><h2 id="_4-مداخلت-کے-بعد-وجوہاتی-تشخیص-اور-اصلاح" tabindex="-1">4. مداخلت کے بعد وجوہاتی تشخیص اور اصلاح <a class="header-anchor" href="#_4-مداخلت-کے-بعد-وجوہاتی-تشخیص-اور-اصلاح" aria-label="Permalink to &quot;4. مداخلت کے بعد وجوہاتی تشخیص اور اصلاح&quot;">​</a></h2><p>محدود مداخلت ختم ہونے کے بعد، آپریشن ٹیم کو فوری طور پر &quot;مداخلت کے بعد وجوہاتی تشخیص&quot; کرنا ہوگا، اینکر نیٹ ورک کے ذریعے مداخلت کے عمل کی وجہ سے پیدا ہونے والی وجوہاتی زنجیر کی تبدیلیوں کی نگرانی کرنی ہوگی۔ تشخیص کے مواد میں شامل ہیں: وجوہاتی انحراف کی شدت، انحراف کے پھیلاؤ کا دائرہ کار، انحراف کے طویل مدتی ارتقاء کا رجحان، اور آیا پیراڈاکس کا خطرہ ہے۔</p><p>اگر تشخیص میں پتا چلتا ہے کہ وجوہاتی انحراف قابل قبول دائرہ کار سے باہر ہے (انحراف کی شدت ہدف علاقے کی کل وجوہاتی مقدار کے 0.01% سے زیادہ)، آپریشن ٹیم کو فوری طور پر &quot;وجوہاتی اصلاح کا طریقہ کار&quot; شروع کرنا ہوگا۔ وجوہاتی اصلاح کے طریقوں میں شامل ہیں: بعد کے وقت کے نوڈز میں معاوضہ دینے والی معلومات کا انجیکشن، اینکر نیٹ ورک کے ذریعے وجوہاتی زنجیر کی باریک ایڈجسٹمنٹ، اور انتہائی صورتوں میں پچھلی مداخلت کے اثرات کو منسوخ کرنے کے لیے دوسری بار پیچھے ہٹنا۔</p><p>تمام مداخلت کے اعمال اور ان کے وجوہاتی تشخیص کے نتائج کو &quot;وقت آپریشن آرکائیو&quot; میں درج کرنا ہوگا، مستقل طور پر محفوظ کرنا ہوگا، بعد کی آڈٹ اور تحقیق کے لیے استعمال کرنا ہوگا۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>پہلے مشاہدہ پھر محدود مداخلت کا رہنما اصول ہینگ یوان ژو کے وقت اور سطح کے آپریشن کے شعبے میں حکمت کا خلاصہ ہے۔ یہ کافی مشاہدے کو پیشگی شرط کے طور پر، سخت حدود کو حد کے طور پر، اور بعد کی تشخیص کو ضمانت کے طور پر لیتا ہے، &quot;جاننے کے بعد کام، کام کی حد&quot; کا ایک آپریشن پیراڈائم بناتا ہے۔ اس رہنما اصول کا بنیادی مقصد تحقیق کے ہاتھ پاؤں باندھنا نہیں ہے، بلکہ اس بات کو یقینی بنانا ہے کہ ہر تحقیق کائنات کے وجوہاتی نظام کو تباہ کرنے کی قیمت پر نہ ہو۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>82-وقت کے پیچھے ہٹنے کے بنیادی اصول</li><li>84-آثار قدیمہ پروٹوکول کا عمومی خاکہ</li><li>89-وقت کے پیراڈاکس روک تھام کا طریقہ کار</li></ul>',32)])])}const s=a(d,[["render",h]]);export{p as __pageData,s as default};
